// 1. 서블릿 그대로 (3.5절)
@RequestMapping("/request-param-v1")
public void requestParamV1(HttpServletRequest request, HttpServletResponse response)
        throws IOException {
    String username = request.getParameter("username");
    int age = Integer.parseInt(request.getParameter("age"));
    response.getWriter().write("ok");
}

// 2. @RequestParam
@ResponseBody
@RequestMapping("/request-param-v2")
public String requestParamV2(@RequestParam("username") String memberName,
                            @RequestParam("age") int memberAge) {
    return "ok";
}

// 3. 이름이 같으면 () 생략
@ResponseBody
@RequestMapping("/request-param-v3")
public String requestParamV3(@RequestParam String username,
                            @RequestParam int age) {
    return "ok";
}

// 4. 단순 타입이면 어노테이션도 생략
@ResponseBody
@RequestMapping("/request-param-v4")
public String requestParamV4(String username, int age) {
    return "ok";
}

// List 로 받는다
@RequestMapping("/request-param-list")
public String requestParamList(@RequestParam List<String> username) {
    log.info("username={}", username);   // [hello, kim]
    return "ok";
}

// MultiValueMap 으로 전부
@RequestMapping("/request-param-multi")
public String requestParamMulti(@RequestParam MultiValueMap<String, String> paramMap) {
    log.info("paramMap={}", paramMap);
    return "ok";
}
